/* Standalone design prototype. Every host, response and transfer is simulated. */
'use strict';
const icons=window.PRISM_ICONS;
const icon=(name)=>icons[name]||icons.circle;
const escapeText=(value)=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const prism=()=>'<svg class="prism-mark" width="28" height="28" viewBox="0 0 28 28" xmlns="http://www.w3.org/2000/svg"><path d="M5 4L25 13 6 25Z" fill="#243c59" stroke="#8bbcff" stroke-width="1"/><path d="M5 4L13 14 6 25" fill="#6ca0d8" fill-opacity=".45"/><path d="M13 14L25 13 6 25Z" fill="#72bfce" fill-opacity=".32"/><path d="M5 4L13 14 25 13" fill="none" stroke="#d5e9ff" stroke-opacity=".7" stroke-width=".7"/></svg>';
const badge=(text,type='green',symbol='')=>`<span class="badge ${type}">${symbol?icon(symbol):'<i class="dot"></i>'}${text}</span>`;
const button=(text,action,name='',kind='')=>`<button type="button" class="btn ${kind}" data-action="${action}">${name?icon(name):''}${text}</button>`;
const servers=[{id:'web-01',name:'web-01',address:'192.0.2.21',user:'deploy',role:'应用节点',folder:'生产环境',status:true},{id:'web-02',name:'web-02',address:'192.0.2.22',user:'deploy',role:'应用节点',folder:'生产环境',status:true},{id:'db-01',name:'db-01',address:'192.0.2.31',user:'postgres',role:'数据库',folder:'生产环境',status:true},{id:'staging',name:'staging',address:'198.51.100.18',user:'deploy',role:'预发布',folder:'开发环境',status:false}];
const views=[['workspace','工作台','grid-1x2'],['connections','连接','hdd-network'],['terminal','终端','terminal'],['files','文件','folder'],['settings','设置','gear'],['motion','动效','activity']];
const state={view:'terminal',server:'web-01',targets:new Set(['web-01','web-02','db-01']),ai:true,picker:false,disconnected:false,empty:false,settings:'models',provider:'Ollama',auth:'password',transfer:'idle',progress:42,modelTest:false,motionPlaying:false,motionPhase:'idle',reduced:window.matchMedia('(prefers-reduced-motion: reduce)').matches};
let modalTrigger=null,toastTimer,transferTimer,motionTimers=[],requestId=0;
const app=document.querySelector('.app');
document.documentElement.dataset.reduce=String(state.reduced);
document.querySelector('#reduce-motion').checked=state.reduced;
const currentHost=()=>servers.find(s=>s.id===state.server)||servers[0];
const hostName=()=>currentHost().name;
const targetChips=()=>[...state.targets].map(id=>`<span class="target-chip"><i class="dot"></i>${escapeText(id)}</span>`).join('')||'<span class="faint">未选择服务器</span>';
const field=(label,value,type='text',extra='')=>`<div class="form-row"><label>${label}</label><input class="field" type="${type}" value="${escapeText(value)}" aria-label="${escapeText(label)}" ${extra}></div>`;
function side(){
 return `<aside class="sidebar"><div class="brand-line">${prism()}棱镜<span class="badge">本地工作区</span></div><div class="side-nav">${views.slice(0,2).map(([id,label,name])=>`<a class="nav-link ${state.view===id?'active':''}" href="#${id}">${icon(name)}${label}${id==='workspace'?'<span class="kbd push">Ctrl 1</span>':''}</a>`).join('')}</div><div class="search">${icon('search')}<input id="host-search" placeholder="搜索连接" aria-label="搜索连接"><span class="kbd">/</span></div><div><div class="side-title"><span>已保存的连接</span><button class="icon-btn" data-action="new-connection" aria-label="新建连接">${icon('plus')}</button></div><div class="host-group">${icon('chevron-down')}${icon('folder')}生产环境<span class="push faint">3</span></div><div id="side-hosts">${servers.slice(0,3).map(s=>`<button class="host-row ${state.server===s.id&&['terminal','files'].includes(state.view)?'active':''}" data-action="select-host" data-host="${s.id}">${icon(s.id==='db-01'?'database':'hdd-network')}<div><div class="host-name">${s.name}</div><div class="host-address">${s.user}@${s.address}</div></div><i class="dot ${state.disconnected&&s.id==='web-01'?'red':'green'}"></i></button>`).join('')}</div><div class="host-group" style="margin-top:18px">${icon('chevron-down')}${icon('folder')}开发环境<span class="push faint">1</span></div><button class="host-row" data-action="staging"><div class="row">${icon('hdd-network')}<div><div class="host-name">staging</div><div class="host-address">最近使用：昨天</div></div></div><i class="dot faint"></i></button></div><button class="side-add" data-action="new-connection">${icon('plus')}新建连接</button><div class="spacer"></div><a href="#settings" class="nav-link ${state.view==='settings'?'active':''}">${icon('gear')}设置<span class="push faint">Ctrl ,</span></a><div class="local-note">${icon('shield-lock')}连接与凭据保存在本机</div></aside>`;
}
function status(){return `<footer class="app-status"><div class="row">${icon('hdd-network')}<span>${state.disconnected?'2':'3'} 台已连接</span></div><span class="status-separator"></span><div class="row">${icon('shield-check')}本机数据存储</div><span class="spacer"></span><span>交互原型</span><span>UTF-8</span><span>Prism 1.9.8</span></footer>`;}
function heading(title,description,actions=''){return `<header class="page-header"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${actions}</div></header>`;}
function workspace(){
 const recent=servers.slice(0,3).map((s,i)=>`<div class="recent-server"><div class="server-tile">${icon(s.id==='db-01'?'database':'hdd-network')}</div><div class="server-detail"><h3>${s.name}<span class="faint" style="margin-left:10px;font-weight:400;font-size:10px">${s.role}</span></h3><p>${s.user}@${s.address}:22</p></div><div class="server-meta">${badge('已连接','green')}<button class="icon-btn" data-action="select-host" data-host="${s.id}" aria-label="打开 ${s.name} 终端">${icon('arrow-up-right')}</button></div></div>`).join('');
 return heading('继续你的服务器工作','终端、文件和下一步操作，都在同一个工作空间。',button(state.empty?'查看已有连接':'查看首次使用','toggle-empty','window','quiet')+button('新建连接','new-connection','plus','primary'))+`<div class="page-body"><div class="workspace-grid"><div>${state.empty?`<section class="panel empty-state"><div class="server-tile">${icon('hdd-network')}</div><h2>连接你的第一台服务器</h2><p>先使用终端和文件管理。需要 AI 辅助时，再配置自己的模型服务。</p>${button('新建连接','new-connection','plus','primary')}${button('导入配置','import','download')}</section>`:`<section class="workspace-section"><div class="section-head"><h2>最近连接</h2><span class="section-label">3 台正在使用</span></div><div class="panel">${recent}</div></section><section class="workspace-section"><div class="section-head"><h2>最近会话</h2><button class="btn quiet sm" data-action="history">查看全部 ${icon('chevron-right')}</button></div><div class="recent-session">${icon('journal-text')}<div><h3>检查生产节点磁盘占用</h3><p>web-01、web-02、db-01</p></div><time>14:32</time>${badge('巡检完成','green')}</div><div class="recent-session">${icon('terminal')}<div><h3>部署前检查容器与端口</h3><p>web-01</p></div><time>昨天</time>${badge('已保存','blue')}</div><div class="recent-session">${icon('folder')}<div><h3>查看服务日志</h3><p>staging</p></div><time>昨天</time><span class="badge">本地会话</span></div></section>`}<div class="note-block">${icon('shield-check')}<div><b>操作之前，先看清目标</b>运行自定义命令或部署阶段前，会展示服务器、命令和验证步骤，由你确认。</div></div></div><div><section class="panel panel-pad"><div class="quiet-art">${prism()}<span>SSH / SFTP / AI</span></div><h2>开始一项任务</h2><button class="task-link" data-action="new-connection"><span class="tile-icon">${icon('hdd-network')}</span><div><h3>连接服务器</h3><p>密码、私钥或 SSH Agent</p></div><span class="arrow">${icon('chevron-right')}</span></button><button class="task-link" data-action="inspect"><span class="tile-icon">${icon('activity')}</span><div><h3>检查主机状态</h3><p>汇总磁盘、服务与监听端口</p></div><span class="arrow">${icon('chevron-right')}</span></button><button class="task-link" data-action="nav-files"><span class="tile-icon">${icon('folder')}</span><div><h3>管理远程文件</h3><p>查看目录，上传或下载</p></div><span class="arrow">${icon('chevron-right')}</span></button></section><div class="note-block" style="margin-top:18px">${icon('cpu')}<div><b>AI 使用你配置的模型</b>可连接模型服务或本地 Ollama。外部模型会接收参与分析的对话和终端输出。<div style="margin-top:12px">${button('配置模型','nav-settings','arrow-up-right','sm')}</div></div></div></div></div></div>`;
}
function connections(){
 const authFields=state.auth==='password'?field('密码','demo-password','password','autocomplete="off" aria-label="演示密码"'):state.auth==='key'?field('私钥文件','~/.ssh/id_ed25519')+field('私钥口令','','password'): '<div class="note-block">'+icon('key')+'使用本机已启动的 SSH Agent，不保存私钥内容。</div>';
 return heading('连接管理','每个连接都有清楚的身份、认证方式和归属。',button('导入配置','import','download')+button('新建连接','new-connection','plus','primary'))+`<div class="page-body"><div class="connections-layout"><div><div class="connection-tools"><div class="search">${icon('search')}<input aria-label="筛选连接" placeholder="按名称、地址或用户筛选"></div>${button('全部分组','groups','chevron-down','sm')}</div><div class="section-head" style="margin-bottom:12px"><span class="section-label">生产环境</span><span class="faint" style="font-size:10px">3 个连接</span></div>${servers.slice(0,3).map((s,i)=>`<div class="connection-card ${i===0?'selected':''}"><div class="server-tile">${icon(i===2?'database':'hdd-network')}</div><div class="connection-info"><h3>${s.name}</h3><p>${s.user}@${s.address}:22</p><div style="margin-top:9px">${badge('指纹已核对','green','shield-check')} <span class="badge">${i===2?'SSH Agent':i===0?'密码认证':'私钥认证'}</span></div></div><div class="connection-extra"><button class="icon-btn" data-action="select-host" data-host="${s.id}" aria-label="打开终端">${icon('arrow-up-right')}</button><small>最近使用 ${i?'14:26':'14:32'}</small></div></div>`).join('')}<div class="section-head" style="margin:25px 0 12px"><span class="section-label">开发环境</span><span class="faint" style="font-size:10px">1 个连接</span></div><div class="connection-card"><div class="server-tile">${icon('hdd-network')}</div><div class="connection-info"><h3>staging</h3><p>deploy@198.51.100.18:22</p><span class="badge" style="margin-top:9px">未连接</span></div><button class="btn sm" data-action="fingerprint">连接</button></div><div class="note-block" style="margin-top:20px">${icon('shield-check')}<div><b>服务器身份变化会阻断连接</b>请通过服务器控制台或管理员核对指纹。即使重置信任，也需要重新发起连接。</div></div></div><section class="form-panel"><div class="row"><h2>编辑连接</h2><span class="badge push">web-01</span></div><p class="subhead">配置保存在当前设备</p>${field('连接名称','web-01')}<div class="form-row inline"><div><label>服务器地址</label><input class="field mono" value="192.0.2.21"></div><div><label>端口</label><input class="field mono" value="22"></div></div>${field('用户名','deploy')}<div class="form-row"><label>认证方式</label><div class="segmented">${[['password','密码'],['key','私钥'],['agent','SSH Agent']].map(([id,name])=>`<button data-action="auth" data-auth="${id}" class="${state.auth===id?'selected':''}">${name}</button>`).join('')}</div></div>${authFields}<div class="form-row"><label>所属分组</label><select class="field"><option>生产环境</option><option>开发环境</option></select></div><div class="form-actions">${button('测试连接','fingerprint','shield-check')}${button('保存连接','save-connection','','primary')}</div><div class="form-security">${icon('shield-lock')}<span>敏感凭据通过系统安全存储保护。导出连接时不包含密码、私钥或口令。</span></div><button class="btn quiet sm" style="margin-top:19px" data-action="fingerprint-changed">预览服务器密钥变化</button></section></div></div>`;
}
function terminalOutput(){const host=currentHost();return `<div class="terminal-top">${icon('folder')}<span>/home/deploy</span><span class="push">bash</span></div><div class="terminal-output"><span class="dim">Last login: Fri Oct 30 14:18:02 2026</span>

<span class="prompt">${host.user}@${host.name}</span><span class="dim">:~$</span> <span class="command">uptime</span>
 14:32:08 up 38 days,  2 users,
 load average: 0.21, 0.18, 0.14

<span class="prompt">${host.user}@${host.name}</span><span class="dim">:~$</span> <span class="command">df -h /var</span>
Filesystem  Size  Used  Avail  Use%  Mounted on
/dev/vda1    80G   63G    17G  <span class="output-amber">79%</span>   /var

<span class="prompt">${host.user}@${host.name}</span><span class="dim">:~$</span> <span class="command">docker ps</span>
<span class="dim">NAMES         STATUS                 PORTS</span>
prism-api     Up 12 days (<span class="output-green">healthy</span>)  3000/tcp
prism-web     Up 12 days             80/tcp
prism-redis   Up 38 days (<span class="output-green">healthy</span>)  6379/tcp

<span class="prompt">${host.user}@${host.name}</span><span class="dim">:~$</span> <span class="cursor"></span></div><div class="terminal-foot">${icon('shield-check')}服务器身份已核对<span class="push"></span><button data-action="disconnect">${state.disconnected?'重新连接 web-01':'预览 web-01 断线'}</button></div>`;}
function picker(){return `<div class="popover" role="group" aria-label="选择操作目标"><h3>选择本次操作的服务器</h3>${servers.map(s=>`<label class="target-option ${!s.status?'disabled':''}"><input type="checkbox" data-target="${s.id}" ${state.targets.has(s.id)?'checked':''} ${!s.status||state.disconnected&&s.id==='web-01'?'disabled':''}><span>${s.name}</span><span class="faint">${s.role}</span><i class="dot ${s.status?'green':'faint'}"></i></label>`).join('')}<p class="hint">仅对选中的已连接服务器执行本次任务。</p></div>`;}
function assistant(){return `<aside class="assistant" aria-label="会话助手" aria-hidden="${!state.ai}" ${state.ai?'':'inert'}><div class="assistant-head">${icon('lightning-charge')}会话助手<button class="icon-btn" data-action="history" aria-label="会话历史">${icon('clock')}</button></div><div class="target-strip"><div class="row"><span>操作目标</span><span class="push">${state.targets.size} 台服务器</span><button class="icon-btn" data-action="targetpicker" aria-expanded="${state.picker}" aria-label="选择操作目标">${icon('sliders')}</button></div><div class="target-chips">${targetChips()}</div>${state.picker?picker():''}</div><div class="chat-scroll"><div class="user-bubble">检查这三台服务器的磁盘和容器状态，只做巡检，按服务器汇总结果。</div><div class="chat-label">${prism()}<span>Prism 助手</span><time>14:32</time></div><p class="chat-summary">巡检已完成。<br><strong>web-01 的磁盘使用率需要关注。</strong></p><div class="inspection"><div class="inspection-row header"><span>服务器</span><span>磁盘</span><span>检查结果</span></div><div class="inspection-row"><span class="mono">web-01</span><span class="mono amber">79%</span>${badge('建议检查','amber')}</div><div class="inspection-row"><span class="mono">web-02</span><span class="mono">35%</span>${badge('正常','green')}</div><div class="inspection-row"><span class="mono">db-01</span><span class="mono">42%</span>${badge('正常','green')}</div></div><p class="chat-summary">容器均在运行。可以先查看 web-01 的日志目录占用，确定空间用在哪里。</p><button class="chat-action" data-action="approval"><span>查看建议命令</span>${icon('arrow-up-right')}</button><div class="inline-tip">${icon('shield-check')}<span>这轮未修改服务器。自定义命令会先展示目标和内容，确认后执行。</span></div></div><div class="composer"><div class="composer-box"><textarea id="chat-input" placeholder="继续排查，或粘贴终端输出…" aria-label="给助手发送请求"></textarea><div class="composer-footer"><button data-action="targetpicker">${icon('hdd-network')}操作目标 ${state.targets.size} 台</button><button data-action="model">${icon('cpu')}我的本地模型 ${icon('chevron-down')}</button><button class="send" data-action="send" aria-label="发送请求">${icon('arrow-up')}</button></div></div><p class="footnote">Enter 发送 · Shift + Enter 换行</p></div></aside>`;}
function terminal(){return `<nav class="session-tabs" aria-label="会话标签"><button class="session-tab ${state.server==='web-01'?'active':''}" data-action="host-tab" data-host="web-01">${icon('terminal')}web-01 <span class="close">×</span></button><button class="session-tab ${state.server==='web-02'?'active':''}" data-action="host-tab" data-host="web-02">${icon('terminal')}web-02 <span class="close">×</span></button><button class="icon-btn" data-action="new-connection" aria-label="新会话">${icon('plus')}</button><span class="spacer"></span><span class="badge">终端工作区</span></nav><header class="session-context"><span class="host-heading">${hostName()}</span>${badge(state.disconnected&&state.server==='web-01'?'已断开':'已连接',state.disconnected&&state.server==='web-01'?'red':'green')}<span class="path">${currentHost().user}@${currentHost().address}</span><span class="spacer"></span><button class="btn quiet sm" data-action="nav-files">${icon('folder')}文件</button><button class="btn sm" data-action="toggle-ai" aria-expanded="${state.ai}">${icon('layout-sidebar')}${state.ai?'收起助手':'打开助手'}</button></header>${state.disconnected?`<div class="connection-alert" role="alert">${icon('exclamation-triangle')}web-01 连接已断开，正在执行的任务状态需要核对。<button class="btn sm push" data-action="disconnect">重新连接</button></div>`:''}<div class="terminal-layout ${state.ai?'':'ai-hidden'}"><section class="terminal-pane">${terminalOutput()}</section>${assistant()}</div>`;}
const fileData=[['logs','directory','—','今天 14:30','drwxr-xr-x'],['releases','directory','—','今天 12:08','drwxr-xr-x'],['backups','directory','—','昨天 03:00','drwx------'],['docker-compose.yml','code','2.4 KB','今天 13:46','-rw-r-----'],['env.example','text','1.2 KB','今天 12:08','-rw-r-----'],['nginx.conf','code','3.8 KB','昨天 16:21','-rw-r--r--'],['README.md','text','6.1 KB','10 月 26 日','-rw-r--r--']];
function transferRows(){const working=state.transfer!=='idle';const progress=working?state.progress:42;const commit=state.transfer==='committing',done=state.transfer==='done',cancel=state.transfer==='cancelled';return `<div class="transfer-row"><div class="transfer-icon">${icon(done?'check2':'cloud-upload')}</div><div class="transfer-detail"><h3>prism-api-2026.10.tar.gz ${badge(done?'已完成':commit?'正在安全保存':cancel?'已取消':'上传中',done?'green':cancel?'amber':'blue')}</h3><div class="target-path">本机 → ${state.transferTarget||'web-01'}:/srv/prism/releases/</div>${cancel?'<div class="failure">已取消，原目标文件保持不变。</div>':''}</div><div class="transfer-progress"><div class="progress-track"><div class="progress-fill" style="--progress:${progress/100}"></div></div><div class="row"><span>${done?'128 / 128':Math.round(progress*1.28)+' / 128'} MB</span><span>${progress.toFixed(progress===99.9?1:0)}%</span></div></div><div class="transfer-controls">${done?'<span class="green">'+icon('check2')+'</span>':`<button class="icon-btn" data-action="cancel-transfer" aria-label="取消传输" ${commit||cancel?'disabled':''}>${icon('x')}</button>`}</div></div><div class="transfer-row"><div class="transfer-icon">${icon('download')}</div><div class="transfer-detail"><h3>docker-compose.yml ${badge('已完成','green')}</h3><div class="target-path">web-01:/srv/prism/ → 本机/Downloads/</div></div><div class="transfer-progress">2.4 KB · 已保存</div><div class="transfer-controls">${button('打开目录','open-folder','folder','quiet sm')}</div></div><div class="transfer-row"><div class="transfer-icon red">${icon('exclamation-triangle')}</div><div class="transfer-detail"><h3>logs-2026-10.tar.gz ${badge('下载失败','red')}</h3><div class="target-path">web-02:/srv/prism/logs/ → 本机/Downloads/</div><div class="failure">连接中断，原文件未被替换。</div></div><div class="transfer-progress">保留失败记录</div><div class="transfer-controls">${button('查看详情','transfer-error','arrow-up-right','quiet sm')}</div></div>`;}
function files(){return heading('远程文件',`${hostName()} · ${currentHost().user}@${currentHost().address} · 已验证服务器身份`,button('新建文件夹','new-folder','folder-plus')+button('上传文件','upload','cloud-upload','primary'))+`<div class="files-body"><div class="files-toolbar"><button class="icon-btn" data-action="parent-folder" aria-label="上一级目录">${icon('arrow-left')}</button><div class="path-field">${icon('folder')}<input aria-label="远端目录" value="/srv/prism" readonly><span class="faint">${icon('shield-check')}</span></div><button class="icon-btn" data-action="refresh-files" aria-label="刷新目录">${icon('arrow-clockwise')}</button><div class="search" style="width:175px">${icon('search')}<input id="file-search" placeholder="在当前目录筛选" aria-label="筛选文件"></div></div><table class="file-table"><thead><tr><th>名称</th><th>大小</th><th>修改时间</th><th>权限</th><th></th></tr></thead><tbody>${fileData.map(([name,type,size,time,perms],i)=>`<tr class="${i===3?'selected':''}" data-file="${name}"><td><div class="file-name ${type==='directory'?'':'code'}"><input type="checkbox" aria-label="选择 ${name}" ${i===3?'checked':''}>${icon(type==='directory'?'folder':type==='code'?'file-earmark-code':'file-earmark-text')}<span>${name}</span></div></td><td class="mono">${size}</td><td>${time}</td><td class="mono" style="font-size:10px">${perms}</td><td><button class="icon-btn" data-action="download" data-name="${name}" aria-label="下载 ${name}">${icon('download')}</button></td></tr>`).join('')}</tbody></table><div class="file-count">7 项 · 已选择 1 项<span class="push" style="float:right">目录属于 ${hostName()}，任务开始后目标固定</span></div><section class="transfers"><div class="transfers-head"><h2>传输任务</h2><span class="badge blue">${state.transfer==='done'||state.transfer==='cancelled'?'0':'1'} 进行中</span><span class="badge red">1 失败</span><button class="push" data-action="start-transfer">${icon('play-fill')} 播放传输过程</button></div><div class="transfer-list" id="transfer-list">${transferRows()}</div></section></div>`;}
function settings(){
 const sections=[['models','模型服务','cpu'],['ai','AI 行为','lightning-charge'],['security','连接与安全','shield-lock'],['appearance','外观与动效','sliders'],['data','数据存储','database'],['updates','应用更新','arrow-down-up']];
 const models=`<div class="settings-intro"><div class="row"><h2>模型服务</h2><span class="spacer"></span>${button('切换服务','provider-picker','chevron-down','sm')}</div><p class="subhead">使用自己的模型服务，或在本机运行 Ollama。</p></div><div class="provider-slab"><div class="provider-logo">${icon('cpu')}</div><div><h3>${escapeText(state.provider)}</h3><p>${state.provider==='Ollama'?'本地模型服务 · 自定义地址':'自定义模型接口 · 演示地址'}</p></div><span class="spacer"></span>${badge('已启用','green')}<button class="switch on" data-action="switch" aria-label="启用 Ollama" role="switch" aria-checked="true"></button></div>${field('服务地址',state.provider==='Ollama'?'http://127.0.0.1:11434/v1':'https://api.example.invalid/v1','url')}<div class="form-row"><label>API Key <span class="faint">（本地服务可留空）</span></label><div class="row"><input class="field" type="password" aria-label="模型服务 API Key" placeholder="保存在系统安全存储中" autocomplete="off"><button class="icon-btn" data-action="key-info" aria-label="密钥说明">${icon('eye-slash')}</button></div></div><div class="row" style="justify-content:space-between;margin-top:22px"><h3>已启用的模型</h3>${button('添加模型','add-model','plus','quiet sm')}</div><div class="settings-model"><div class="model-row"><span class="server-tile" style="width:30px;height:30px">${icon('cpu')}</span><div><div class="model-name">${state.provider==='Ollama'?'我的本地模型':'我的服务模型'}</div><p>模型 ID 按实际服务配置</p></div><span class="spacer"></span><span class="badge blue">工具调用</span><button class="icon-btn" data-action="model-parameters" aria-label="模型参数">${icon('sliders')}</button></div></div><div class="setting-note">${icon('shield-check')}<span id="model-test-result">${state.modelTest?'对话连接测试通过。该结果仅验证模型对话连接，不代表工具调用已验证。':'连接测试验证地址、认证和普通对话。巡检还需要模型支持工具调用，请按模型实际能力配置。'}</span></div><div class="settings-footer"><p>修改仅保存在当前设备。</p><div class="row">${button(state.modelTest?'重新测试':'测试模型连接','test-model','activity')}${button('保存配置','save-model','','primary')}</div></div>`;
 const appearance=`<div class="settings-intro"><h2>外观与动效</h2><p class="subhead">让工作区清楚、安静，并适合长时间使用。</p></div><div class="setting-row"><div><h3>界面主题</h3><p>烟晶深色与清透浅色使用相同的信息层级。</p></div>${button('切换主题','theme','moon','sm')}</div><div class="swatches"><div class="swatch" style="background:#101923"></div><div class="swatch" style="background:#17232f"></div><div class="swatch" style="background:#223242"></div><div class="swatch" style="background:#8db9ff"></div><div class="swatch" style="background:#77d7b8"></div></div><div class="setting-row"><div><h3>减少动态效果</h3><p>关闭位移和缩放，保留短暂的颜色与透明度反馈。</p></div><button class="switch ${state.reduced?'on':''}" role="switch" aria-checked="${state.reduced}" aria-label="减少动态效果" data-action="reduce"></button></div><div class="setting-row"><div><h3>界面字体</h3><p>Noto Sans SC · 终端使用等宽字体</p></div><span class="badge">标准</span></div><div class="setting-row"><div><h3>玻璃材质</h3><p>只在窗口边缘与浮层保留轻度通透，终端画布保持稳定。</p></div><button class="switch on" data-action="switch" role="switch" aria-checked="true" aria-label="玻璃材质"></button></div><div class="setting-note">${icon('activity')}动效只解释操作与状态，不让光晕、日志或终端文字持续运动。</div>`;
 const generic=state.settings==='ai'?`<h2>AI 行为</h2><p class="subhead">确认、会话历史与上下文保留。</p>${[['只读操作自动批准','关闭后，在读取服务器内容前确认。',false],['保存对话历史','保存在本机，可恢复或删除。',true]].map(([t,d,on])=>`<div class="setting-row"><div><h3>${t}</h3><p>${d}</p></div><button class="switch ${on?'on':''}" data-action="switch" role="switch" aria-checked="${on}" aria-label="${t}"></button></div>`).join('')}<div class="setting-note">${icon('shield-lock')}自定义命令、部署阶段和环境文档修改，始终展示目标与内容后确认。</div>`:state.settings==='security'?`<h2>连接与安全</h2><p class="subhead">让每次连接都指向你核对过的服务器。</p><div class="setting-row"><div><h3>服务器指纹</h3><p>按地址与端口保存；密钥变化时阻断连接。</p></div>${button('查看确认流程','fingerprint','shield-check','sm')}</div><div class="setting-row"><div><h3>凭据保护</h3><p>系统安全存储不可用时，不保存敏感凭据。</p></div>${badge('已启用','green')}</div>`:state.settings==='data'?`<h2>数据存储</h2><p class="subhead">连接、模型配置和会话历史保存在当前设备。</p><div class="setting-row"><div><h3>本机数据目录</h3><p>备份前请退出应用，远端环境文档需另行备份。</p></div>${button('打开目录','open-folder','folder','sm')}</div><div class="setting-row"><div><h3>导出配置</h3><p>不包含密码、私钥和模型密钥。</p></div>${button('导出配置','export','download','sm')}</div>`:`<h2>应用更新</h2><p class="subhead">后台检查和下载，准备好后由你安装。</p><div class="provider-slab" style="margin-top:22px">${icon('check-circle')}<div><h3>当前版本 1.9.8</h3><p>演示状态，不执行真实更新。</p></div><span class="spacer"></span>${button('检查更新','check-update','arrow-repeat','sm')}</div>`;
 return heading('设置','本机配置，按你的工作方式调整。',button('打开项目','project','arrow-up-right','quiet'))+`<div class="page-body"><div class="settings-layout"><nav class="settings-nav" aria-label="设置分区">${sections.map(([id,name,symbol])=>`<button class="${state.settings===id?'selected':''}" data-action="settings-section" data-section="${id}">${icon(symbol)}${name}</button>`).join('')}</nav><section class="settings-main">${state.settings==='models'?models:state.settings==='appearance'?appearance:generic}</section></div></div>`;
}
function motion(){return heading('让每一次变化，都有来由','按下播放，查看面板、目标、确认和结果如何衔接。',button('在完整界面中体验','nav-terminal','arrow-up-right')+button('播放一次','play-motion','play-fill','primary'))+`<div class="page-body"><div class="motion-layout"><div><div class="motion-stage" data-phase="${state.motionPhase}"><div class="row">${icon('terminal')}web-01 <span class="push">交互动效演示</span></div><div class="motion-terminal"><span style="color:#83c6b2">deploy@web-01</span>:~$<br>选择目标，查看命令，再确认执行。<br><span style="color:#72869a">终端文字不使用打字机动画。</span><br><br><span id="motion-terminal-result"></span></div><aside class="motion-drawer" id="motion-drawer"><h3>${icon('lightning-charge')} 会话助手</h3><p class="section-label">操作目标</p><div class="target-option"><span class="dot green"></span>web-01<span class="push blue" id="motion-target-check">${icon('check2')}</span></div><div class="target-option"><span class="dot green"></span>web-02<span class="push blue" id="motion-target-second" style="opacity:0">${icon('check2')}</span></div><div class="rule"></div><p class="motion-state" id="motion-state">等待选择</p></aside><div class="motion-confirm" id="motion-confirm"><h3>确认本次操作</h3><p>web-01 / web-02 · 目标与命令清楚可见</p><code class="mono" style="font-size:11px">df -h /var</code><button class="btn primary sm" disabled>仅批准本次</button></div></div><div class="motion-playhead"><span id="motion-playhead"></span></div><div class="motion-steps"><span>面板展开</span><span>选择目标</span><span>确认命令</span><span>查看结果</span></div><div class="motion-spec-list"><div class="motion-spec-row">${icon('layout-sidebar')}面板开合<code>220ms / 160ms</code></div><div class="motion-spec-row">${icon('hdd-network')}目标选择<code>立即勾选 / 120ms 着色</code></div><div class="motion-spec-row">${icon('shield-check')}确认与退出<code>180ms / 120ms</code></div><div class="motion-spec-row">${icon('cloud-upload')}传输与提交<code>150ms / linear</code></div><div class="motion-spec-row">${icon('exclamation-triangle')}断线与停止<code>状态立即 / 120ms 淡入</code></div></div></div><aside><div class="motion-reduce"><div class="row" style="justify-content:space-between"><h3>减少动态效果</h3><button class="switch ${state.reduced?'on':''}" data-action="reduce" role="switch" aria-checked="${state.reduced}" aria-label="减少动态效果"></button></div><p>保留同一条操作路径。移除位移、缩放与弹簧，用 70ms 淡换表达状态。</p></div><h3 style="margin:21px 0 14px">动效约束</h3><ul class="motion-rules"><li>先响应操作，再表现过渡；键盘焦点不等待动画。</li><li>目标勾选立即生效，确认内容保持静止可读。</li><li>传输字节完成后，等待安全提交才显示 100%。</li><li>断线和失败信息持续保留，不自动消失。</li><li>不使用终端打字机、持续光晕或整页滑入。</li></ul><div class="note-block" style="margin-top:22px">${icon('play-fill')}时间仅用于交互演示，不代表真实服务器执行耗时。</div></aside></div></div>`;}
function render(){
 const view=views.find(([id])=>id===state.view)?state.view:'terminal';state.view=view;
 document.querySelector('#review-nav').innerHTML=views.map(([id,name])=>`<a href="#${id}" class="${id===view?'active':''}" ${id===view?'aria-current="page"':''}>${name}</a>`).join('');
 document.querySelector('#theme-toggle').innerHTML=icon(document.documentElement.dataset.theme==='light'?'moon':'sun');
 app.dataset.view=view;
 app.innerHTML=`<div class="window-bar">${prism()}<span>棱镜 Prism</span><span class="proto-label">交互原型 · 演示服务器与模型数据</span><span class="spacer"></span><div class="window-actions" aria-hidden="true"><span>−</span><i></i><span>×</span></div></div><div class="workbench">${side()}<main class="main" id="main-content">${({workspace,connections,terminal,files,settings,motion})[view]()}</main></div>${status()}`;
 app.querySelectorAll('.form-row label').forEach((label,i)=>{const control=label.nextElementSibling;if(control?.matches('input,select,textarea')){control.id ||= 'design-field-'+i;label.htmlFor=control.id;}});
 document.documentElement.dataset.ready='true';
}
function navigate(view){if(location.hash==='#'+view){state.view=view;render();}else location.hash=view;}
function toast(message){clearTimeout(toastTimer);app.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.innerHTML=icon('check-circle')+`<span>${escapeText(message)}</span>`;app.append(n);requestAnimationFrame(()=>n.classList.add('visible'));toastTimer=setTimeout(()=>{n.classList.remove('visible');setTimeout(()=>n.remove(),150)},3000);}
function openModal(kind,trigger=document.activeElement){
 app.querySelector('.modal-backdrop')?.remove();modalTrigger=trigger;
 const host=currentHost();const changed=kind==='fingerprint-changed';let title='确认 SSH 服务器指纹',symbol='shield-check',content='',actions='';
 if(kind==='fingerprint'||changed){title=changed?'服务器身份已改变':'确认 SSH 服务器指纹';symbol=changed?'exclamation-triangle':'shield-check';content=`<p>${changed?'服务器公钥与已保存记录不一致，本次连接已阻止。请通过服务器控制台或管理员核对新旧指纹。':'首次连接这台服务器，请通过可信渠道核对其指纹。确认之前不会发送登录密码或进行私钥认证。'}</p><div class="identity-block"><div class="row"><span>staging</span><span class="push mono">198.51.100.18:22</span></div></div>${changed?'<div class="identity-block"><div class="section-label">已保存指纹</div><code>SHA256:fU2sQ8kT3mP1yL6vR4xN9aJ7cH0eW5bD2gS8iO3zK1E</code></div>':''}<div class="identity-block"><div class="section-label">当前指纹 · ssh-ed25519</div><code>SHA256:K8nP3jW7qB1tF6vC9xR2mH5dL0sY4eA8uG3iO6zN1kE</code></div><div class="dialog-note">${icon('exclamation-triangle')}<span>示例指纹，仅用于设计演示。${changed?'密钥变化可能来自重装或网络冒充，勿仅因连接失败而重置信任。':'不确定时请选择取消，先核对服务器身份。'}</span></div>`;actions=button('取消连接','close-modal')+button(changed?'已核对，查看重置流程':'信任并连接',changed?'reset-trust':'trust','','primary');}
 else if(kind==='approval'){title='确认本次操作';content=`<p>先查看占用，不删除文件。这里只批准下面这一条命令，后续操作仍需单独确认。</p><div class="section-label">执行目标</div><div class="target-chips"><span class="target-chip"><i class="dot"></i>web-01</span><span class="badge">deploy@192.0.2.21</span></div><div class="section-label">将执行的命令</div><pre class="command-block">du -sh /var/log/* | sort -hr | head -n 10</pre><div class="approval-meta"><span>范围：只统计目录大小</span><span>超时：30 秒</span></div><div class="rule"></div><div class="dialog-note">${icon('shield-check')}<span>确认内容与执行目标固定。即使切换标签，本次命令也不会发往其他服务器。</span></div>`;actions=button('取消','close-modal')+button('确认本次操作','approve','','primary');}
 else if(kind==='upload'){title='确认覆盖文件';symbol='cloud-upload';content=`<p>目标位置已有同名文件。新文件完整传输后，才会替换原文件。</p><div class="identity-block"><div class="section-label">服务器与目标路径</div><code>${host.name} · ${host.user}@${host.address}:22</code><code>/srv/prism/releases/prism-api-2026.10.tar.gz</code></div><div class="dialog-note">${icon('shield-check')}<span>这是交互演示，不会读取或上传本机文件。</span></div>`;actions=button('取消','close-modal')+button('覆盖并上传','confirm-upload','','primary');}
 else if(kind==='transfer-error'){title='文件未完成下载';symbol='exclamation-triangle';content='<p>连接中断，原目标文件未被替换。先重新连接服务器，再确认是否重新下载。</p><div class="identity-block"><div class="section-label">原定来源</div><code>web-02:/srv/prism/logs/logs-2026-10.tar.gz</code><div class="section-label" style="margin-top:12px">原定目标</div><code>本机/Downloads/logs-2026-10.tar.gz</code></div><div class="dialog-note">'+icon('shield-check')+'<span>任务目标保持不变。不会自动重试，失败记录会保留。</span></div>';actions=button('关闭','close-modal')+button('重新连接','reconnect','','primary');}
 else if(kind==='provider-picker'){title='选择模型服务';symbol='cpu';content='<p>选择本地或外部模型服务。这里仅演示配置流程，不发送 API 请求，也不保存密钥。</p>'+['Ollama','OpenAI 兼容服务','自定义服务'].map(name=>`<button class="task-link" data-action="select-provider" data-provider="${name}"><span class="tile-icon">${icon('cpu')}</span><div><h3>${name}</h3><p>${name==='Ollama'?'本机模型服务':'填写自己的服务地址、密钥与模型 ID'}</p></div>${icon('chevron-right')}</button>`).join('');actions=button('取消','close-modal');}
 else if(kind==='new-folder'){title='新建文件夹';symbol='folder-plus';content=field('文件夹名称','new-folder','text','id="folder-name"')+`<div class="identity-block"><div class="section-label">固定目标</div><code>${host.name}:/srv/prism/</code></div>`;actions=button('取消','close-modal')+button('创建文件夹','create-folder','','primary');}
 else{title='会话历史';symbol='clock';content='<p>会话保存在本机。下列内容均为设计演示数据。</p><div class="recent-session">'+icon('journal-text')+'<div><h3>检查生产节点磁盘占用</h3><p>web-01、web-02、db-01</p></div><span class="badge green">已保存</span></div><div class="recent-session">'+icon('journal-text')+'<div><h3>部署前检查容器与端口</h3><p>web-01</p></div><span class="badge">昨天</span></div>';actions=button('关闭','close-modal')+button('恢复会话','restore-history','','primary');}
 const wrap=document.createElement('div');wrap.className='modal-backdrop';wrap.dataset.host=host.id;wrap.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="modal-head"><div class="dialog-icon">${icon(symbol)}</div><h2 id="dialog-title">${title}</h2><button class="icon-btn" aria-label="关闭对话框" data-action="close-modal">${icon('x')}</button></div><div class="modal-body">${content}</div><div class="modal-actions">${actions}</div></section>`;app.append(wrap);requestAnimationFrame(()=>{wrap.classList.add('open');wrap.querySelector('.modal-actions button')?.focus({preventScroll:true});});
}
function closeModal(after){const wrap=app.querySelector('.modal-backdrop');if(!wrap){after?.();return;}wrap.classList.add('leaving');wrap.classList.remove('open');setTimeout(()=>{wrap.remove();if(modalTrigger?.isConnected)modalTrigger.focus({preventScroll:true});after?.();},state.reduced?70:120);}
function updateTransfers(){
 const n=document.querySelector('#transfer-list');if(!n)return;
 if(n.dataset.stage!==state.transfer){n.innerHTML=transferRows();n.dataset.stage=state.transfer;}
 else{const row=n.querySelector('.transfer-row');row.querySelector('.progress-fill')?.style.setProperty('--progress',String(state.progress/100));const labels=row.querySelectorAll('.transfer-progress .row span');if(labels.length){labels[0].textContent=Math.round(state.progress*1.28)+' / 128 MB';labels[1].textContent=state.progress.toFixed(state.progress===99.9?1:0)+'%';}}
 const count=n.closest('.transfers').querySelector('.transfers-head .badge');count.textContent=['done','cancelled'].includes(state.transfer)?'0 进行中':'1 进行中';
}
function startTransfer(host=state.server){clearInterval(transferTimer);state.transferTarget=host;state.transfer='running';state.progress=0;updateTransfers();let step=0;transferTimer=setInterval(()=>{step++;if(state.transfer!=='running'){clearInterval(transferTimer);return;}state.progress=Math.min(99.9,step*17.8);if(step>=6){state.transfer='committing';updateTransfers();clearInterval(transferTimer);transferTimer=setTimeout(()=>{state.transfer='done';state.progress=100;updateTransfers();toast('演示传输已完成，目标文件已安全保存');},700);}else updateTransfers();},320);}
function setReduce(value){state.reduced=value;document.documentElement.dataset.reduce=String(value);document.querySelector('#reduce-motion').checked=value;document.querySelectorAll('[data-action=reduce]').forEach(n=>{n.classList.toggle('on',value);n.setAttribute('aria-checked',String(value));});if(value)document.getAnimations().forEach(a=>{try{a.finish();}catch{a.cancel();}});}
function toggleTheme(){const root=document.documentElement;root.dataset.switching='true';root.dataset.theme=root.dataset.theme==='light'?'dark':'light';document.querySelector('#theme-toggle').innerHTML=icon(root.dataset.theme==='light'?'moon':'sun');requestAnimationFrame(()=>delete root.dataset.switching);}
function playMotion(){
 if(state.view!=='motion')return;motionTimers.forEach(clearTimeout);motionTimers=[];state.motionPlaying=true;state.motionPhase='start';app.dataset.motion='playing';
 const drawer=document.querySelector('#motion-drawer'),confirm=document.querySelector('#motion-confirm'),mark=document.querySelector('#motion-target-second'),phase=document.querySelector('#motion-state'),result=document.querySelector('#motion-terminal-result'),head=document.querySelector('#motion-playhead');
 drawer.classList.remove('open');confirm.classList.remove('open');mark.style.opacity='0';result.textContent='';head.style.transform='scaleX(0)';
 const schedule=(time,fn)=>motionTimers.push(setTimeout(fn,time));
 schedule(150,()=>{drawer.classList.add('open');phase.textContent='选择操作目标';head.style.transform='scaleX(.2)';});
 schedule(900,()=>{mark.style.opacity='1';phase.textContent='2 台服务器已选中';head.style.transform='scaleX(.4)';});
 schedule(1600,()=>{confirm.classList.add('open');head.style.transform='scaleX(.6)';});
 schedule(2550,()=>{confirm.classList.remove('open');phase.textContent='正在读取磁盘信息';head.style.transform='scaleX(.8)';});
 schedule(3350,()=>{phase.innerHTML=icon('check-circle')+' 巡检完成';phase.classList.add('green');result.innerHTML='<span style="color:#77d7b8">web-01 / web-02 · 已完成</span><br>执行结果按服务器保留。';head.style.transform='scaleX(1)';state.motionPlaying=false;state.motionPhase='done';app.dataset.motion='done';});
}
document.addEventListener('click',e=>{
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;
 const nav=action.match(/^nav-(.+)$/);if(nav){navigate(nav[1]);return;}
 if(action==='new-connection'){state.auth='password';navigate('connections');}
 else if(action==='select-host'||action==='host-tab'){state.server=el.dataset.host;navigate('terminal');}
 else if(action==='provider-picker')openModal('provider-picker',el);
 else if(action==='select-provider'){const provider=el.dataset.provider;closeModal(()=>{state.provider=provider;state.modelTest=false;render();});}
 else if(action==='toggle-empty'){state.empty=!state.empty;render();}
 else if(action==='inspect'){state.ai=true;navigate('terminal');}
 else if(action==='auth'){state.auth=el.dataset.auth;render();}
 else if(action==='fingerprint'||action==='fingerprint-changed'||action==='approval'||action==='history'||action==='upload'||action==='new-folder'||action==='transfer-error')openModal(action,el);
 else if(action==='close-modal')closeModal();
 else if(action==='trust')closeModal(()=>toast('演示：指纹已核对，可以建立连接'));
 else if(action==='reset-trust')closeModal(()=>toast('演示：已重新核对信任，请再次连接'));
 else if(action==='approve')closeModal(()=>toast('演示：命令已确认，执行目标固定为 web-01'));
 else if(action==='confirm-upload'){const target=app.querySelector('.modal-backdrop').dataset.host;closeModal(()=>{if(state.view!=='files')navigate('files');setTimeout(()=>startTransfer(target),50);});}
 else if(action==='toggle-ai'){state.ai=!state.ai;document.querySelector('.terminal-layout').classList.toggle('ai-hidden',!state.ai);el.innerHTML=icon('layout-sidebar')+(state.ai?'收起助手':'打开助手');el.setAttribute('aria-expanded',String(state.ai));const panel=app.querySelector('.assistant');panel.inert=!state.ai;panel.setAttribute('aria-hidden',String(!state.ai));}
 else if(action==='targetpicker'){state.picker=!state.picker;const strip=document.querySelector('.target-strip');if(strip){strip.querySelector('.popover')?.remove();if(state.picker)strip.insertAdjacentHTML('beforeend',picker());strip.querySelector('[data-action=targetpicker]')?.setAttribute('aria-expanded',String(state.picker));}}
 else if(action==='disconnect'){state.disconnected=!state.disconnected;if(state.disconnected)state.targets.delete('web-01');render();}
 else if(action==='reconnect')closeModal(()=>{state.disconnected=false;toast('演示：请核对连接后重新发起任务');});
 else if(action==='theme')toggleTheme();
 else if(action==='reduce')setReduce(!state.reduced);
 else if(action==='switch'){const on=el.classList.toggle('on');el.setAttribute('aria-checked',String(on));}
 else if(action==='settings-section'){state.settings=el.dataset.section;render();}
 else if(action==='test-model'){state.modelTest=true;document.querySelector('#model-test-result').textContent='对话连接测试通过。该结果仅验证模型对话连接，不代表工具调用已验证。';el.innerHTML=icon('check-circle')+'对话连接通过';}
 else if(action==='save-model'||action==='save-connection')toast('演示：配置已保存到当前工作区');
 else if(action==='model'||action==='add-model'||action==='model-parameters'){state.settings='models';navigate('settings');if(action==='model-parameters')setTimeout(()=>toast('模型参数：推理强度、温度与输出限制按模型能力显示'),30);}
 else if(action==='start-transfer')startTransfer();
 else if(action==='cancel-transfer'){if(state.transfer!=='committing'){clearInterval(transferTimer);state.transfer='cancelled';updateTransfers();}}
 else if(action==='play-motion')playMotion();
 else if(action==='create-folder'){const target=app.querySelector('.modal-backdrop').dataset.host;closeModal(()=>toast('演示：文件夹已创建在原定的 '+target+':/srv/prism/'));}
 else if(action==='restore-history')closeModal(()=>{navigate('terminal');toast('演示：已恢复本机会话');});
 else if(action==='send'){const input=document.querySelector('#chat-input');if(!input?.value.trim()){input?.focus();return;}if(!state.targets.size){toast('请先选择至少一台已连接服务器');return;}const request=input.value;input.value='';const chat=document.querySelector('.chat-scroll');chat.insertAdjacentHTML('beforeend',`<div class="user-bubble" style="margin-top:16px">${escapeText(request)}</div><div class="inline-tip">${icon('shield-check')}演示请求已收到，不会执行真实操作。</div>`);chat.scrollTop=chat.scrollHeight;}
 else if(action==='staging')openModal('fingerprint',el);
 else if(action==='download')toast(`演示：下载目标固定为 ${hostName()}:/srv/prism/${el.dataset.name}`);
 else if(action==='open-folder')toast('交互演示，不会打开或读取本机目录');
 else if(action==='import'||action==='export')toast('配置导入与导出不包含已保存的密码或密钥');
 else if(action==='parent-folder'||action==='refresh-files')toast('演示：当前目录为 '+hostName()+':/srv/prism/');
 else if(action==='project')toast('项目地址：github.com/aides-hik/AI-ssh');
 else if(action==='check-update')toast('交互演示，不检查或下载真实更新');
 else if(action==='key-info')toast('密钥只在系统安全存储中保存，导出配置不携带密钥');
 else if(action==='groups')toast('连接可按生产环境、开发环境和自建文件夹分组');
});
document.addEventListener('change',e=>{if(e.target.matches('[data-target]')){const id=e.target.dataset.target;if(e.target.checked)state.targets.add(id);else state.targets.delete(id);document.querySelector('.target-chips').innerHTML=targetChips();document.querySelector('.target-strip .push').textContent=`${state.targets.size} 台服务器`;const trigger=document.querySelector('.composer-footer [data-action=targetpicker]');if(trigger)trigger.innerHTML=icon('hdd-network')+'操作目标 '+state.targets.size+' 台';}if(e.target.id==='reduce-motion')setReduce(e.target.checked);});
document.addEventListener('input',e=>{if(e.target.id==='host-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('#side-hosts .host-row').forEach(n=>n.hidden=!n.textContent.toLowerCase().includes(q));}if(e.target.id==='file-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-file]').forEach(n=>n.hidden=!n.dataset.file.toLowerCase().includes(q));}});
document.addEventListener('keydown',e=>{const modal=app.querySelector('.modal-backdrop');if(e.key==='Escape'){if(modal)closeModal();else if(state.picker){state.picker=false;app.querySelector('.popover')?.remove();const trigger=app.querySelector('.target-strip [data-action=targetpicker]');trigger?.setAttribute('aria-expanded','false');trigger?.focus();}return;}if(modal&&e.key==='Tab'){const targets=[...modal.querySelectorAll('button:not([disabled]),input,select,textarea,a[href]')];if(e.shiftKey&&document.activeElement===targets[0]){e.preventDefault();targets.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===targets.at(-1)){e.preventDefault();targets[0]?.focus();}}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();document.querySelector('[data-action=send]')?.click();}});
document.querySelector('#theme-toggle').addEventListener('click',toggleTheme);
window.addEventListener('hashchange',()=>{motionTimers.forEach(clearTimeout);state.picker=false;state.view=location.hash.slice(1)||'terminal';render();});
window.prismPrototype={state,navigate,openModal,closeModal,playMotion,startTransfer,setReduce,render};
state.view=location.hash.slice(1)||'terminal';render();
